"""French table reminders, checked against the supplied editions.

Each card is a short synthesis, not a replacement for its source section.
Page numbers below are PDF page numbers, not printed page numbers.
"""
import hashlib

RULES=[]


def R(source,page,title,summary,steps=(),topic='combat',kind='rule',optional=False,original=None,fields=(),warning=None,tags=()):
    e=dict(id=source+'-rappel-'+hashlib.sha1(title.encode()).hexdigest()[:12],source=source,page=page,printedPage=page-(1 if source in ('wild','companion') else 2),title=title,summary=summary,steps=list(steps),topic=topic,kind=kind,optional=optional,tags=list(tags),fields=list(fields))
    if original:e['originalTitle']=original
    if warning:e['warning']=warning
    RULES.append(e)


R('core',41,'Réserve de dés et succès','Réunir la compétence et l’attribut indiqués, puis appliquer les modificateurs. Chaque résultat de 5 ou 6 sur un D6 est un succès. Le total des faces ne sert pas à déterminer la réussite d’un test ordinaire.',tags=('dés','test','dice pool','hits'))
R('core',41,'Tests simples et tests opposés','Un test simple réussit si les succès atteignent le seuil. Dans un test opposé, comparer les succès des deux parties ; leur différence donne les succès nets. Les règles de l’action précisent les conséquences d’une égalité.',tags=('seuil','réussite','opposition'))
R('core',41,'Test étendu','Cumuler les succès de plusieurs jets pour atteindre le seuil total. Chaque jet consomme l’intervalle prévu et, après le premier, la réserve perd cumulativement un dé. Arrêter quand le seuil est atteint ou que la réserve est épuisée.',tags=('extended test','intervalle'))
R('core',42,'Travail d’équipe','Les assistants effectuent le même test avant le leader. Leurs succès ajoutent des dés à sa réserve, dans la limite du rang de la compétence du leader, ou de son plus haut attribut pour un test à deux attributs. En initiative, les assistants doivent conserver l’action majeure Assister.',tags=('aider','assistant','teamwork'))
R('core',42,'Complication et échec critique','Il y a complication si plus de la moitié des dés montrent 1. S’il n’y a en plus aucun succès, c’est un échec critique. Une complication peut accompagner une réussite ; elle ne l’annule pas automatiquement.',tags=('glitch','critical glitch'))
R('core',43,'Acheter des succès','Lorsque le MJ l’autorise, obtenir un succès par tranche complète de quatre dés plutôt que lancer. Cette option sert notamment aux tâches sans pression ; elle n’est pas un droit automatique pour toutes les actions.')
R('core',44,'Attributs et maximum augmenté','Un attribut modifié ne peut dépasser son rang actuel de plus de 4. Un attribut physique ou mental réduit à 0 neutralise le personnage jusqu’à ce qu’il regagne au moins un point.',topic='personnage')
R('core',45,'Moniteurs d’état et blessures','Les dommages physiques et étourdissants ont des moniteurs distincts. Appliquer les modificateurs de blessures prévus lorsque des cases sont cochées. Les profils de créatures et de PNJ peuvent fournir directement leurs moniteurs : conserver ces valeurs.',topic='personnage',tags=('PV','points de vie','santé','condition monitor'))
R('core',46,'Actions d’un round de combat','Un round représente environ trois secondes. Chaque protagoniste a un tour et reçoit une action majeure, une action mineure, puis une mineure par dé d’initiative. Une majeure peut remplacer une mineure ; quatre mineures peuvent devenir une majeure. Respecter le plafond et les indications I/L de l’action.',tags=('action economy','tour','majeure','mineure'))
R('core',112,'Initiative','Au début du combat, additionner Réaction + Intuition et la somme des dés d’initiative. Agir du score le plus élevé au plus faible. Le même ordre est conservé pendant le combat sauf effet qui le modifie ; on ne soustrait pas 10 pour créer des passes supplémentaires.',tags=('ordre','vitesse','initiative dice'))
R('core',110,'Résoudre une attaque','Une attaque ordinaire suit les cinq étapes de la procédure de combat.',steps=('Constituer la réserve de l’attaquant : compétence appropriée + Agilité ; pour une arme montée, Ingénierie + Logique. Le défenseur réunit Réaction + Intuition, avec les modificateurs applicables.','Comparer le SO à la portée utilisée au SD de la cible. Une différence d’au moins 4 donne un point d’Atout au camp avantagé ; examiner aussi la situation, les traits et le matériel.','Lancer et appliquer l’unique dépense d’Atout autorisée pour l’action. Les succès nets augmentent la VD ; dans cette édition française, une égalité inflige la VD de base.','La cible résiste avec sa Constitution : chaque succès retranche un point de dommages.','Reporter les dommages restants sur le bon moniteur et appliquer les effets secondaires correspondants.'),tags=('attaque','tirer','défense','SO','SD','VD'))
R('core',111,'Armure, SO et SD','Le Score Offensif se compare au Score Défensif pour attribuer l’Atout. Cette comparaison n’est ni le test d’attaque ni la résistance aux dommages. Une armure ordinaire améliore le SD ; le jet d’encaissement ordinaire utilise la Constitution.',tags=('armor','defense rating','attack rating','armure','protection'))
R('core',51,'Gagner et conserver l’Atout','Examiner l’avantage relatif, le matériel et les traits. Le maximum conservé est de 7 points. Appliquer les limites de gain de l’édition et de l’action utilisée ; un avantage artificiellement provoqué sans enjeu ne doit pas permettre d’accumuler indéfiniment de l’Atout.',tags=('edge','limite','gain'))
R('core',52,'Dépenser de l’Atout','Une seule utilisation d’Atout est autorisée par action. Choisir un bonus ou une action d’Atout et respecter son moment : avant le jet, après le jet ou libre. Les remises diminuent le coût mais ne constituent pas des points d’Atout gagnés.',tags=('edge boost','remise','bonus'))
R('core',54,'Cramer un point d’Atout','Cramer de l’Atout diminue définitivement l’attribut, contrairement à la dépense des points disponibles. Les usages extraordinaires, dont survivre à une mort certaine, sont détaillés dans la source. Racheter le rang exige ensuite le coût normal en Karma.',topic='personnage',tags=('mort','survivre','not dead yet'))
R('core',55,'Dé libre','Le dé libre remplace un dé ordinaire de la réserve. Sur 5 ou 6, il compte pour trois succès. Sur 1, les 5 des autres dés ne comptent plus comme succès ; les 6 comptent toujours. Les autres faces n’apportent aucun succès.',tags=('wild die','dé sauvage'))
R('core',114,'Surprise','La perception de l’attaque et le test de surprise déterminent ce qu’une cible peut faire. Appliquer les restrictions aux actions et à la défense prévues par cette situation avant de résoudre l’attaque ; être surpris ne se résume pas à une baisse du SD.',tags=('embuscade','surprise'))
R('core',114,'Portées et profil d’une arme','Lire le SO dans la colonne de portée correspondant à la distance. Une colonne sans valeur n’autorise pas l’attaque à cette portée. Le mode de tir, les munitions et les accessoires modifient les valeurs indiquées par leurs propres règles.',tags=('range','portée','arme','score offensif'))
R('core',117,'Environnement et visibilité','Comparer les difficultés que subissent les adversaires et les moyens dont ils disposent pour les compenser. L’avantage de situation peut attribuer de l’Atout ; ne pas appliquer systématiquement les anciens malus d’autres éditions.',tags=('obscurité','brouillard','lumière','vent'))
R('core',118,'Obstacles et barrières','Une attaque sur une barrière ou à travers une barrière utilise ses caractéristiques de Structure et de Blindage. Suivre la procédure de perforation avant d’appliquer des dommages à une cible de l’autre côté.',tags=('mur','porte','vitre','barrier'))
R('core',120,'Groupes de figurants','Plusieurs figurants peuvent être résolus comme un groupe pour accélérer le combat. Le meneur utilise la réserve et les augmentations de groupe prévues, puis les dommages se reportent selon la procédure des figurants. Cette règle diffère d’un simple test d’équipe.',topic='mj',tags=('grunt group','groupe','PNJ','professionnalisme'))
R('core',121,'Grenades, explosions et déviation','Déterminer le point d’impact et la déviation, puis la distance réelle de chaque cible à l’explosion. Utiliser les VD et zones d’effet de l’explosif. La procédure ne se traite pas comme un tir ordinaire contre une seule cible.',tags=('blast','grenade','scatter','explosif'))
R('core',125,'Premiers soins et médikit','Les premiers soins, le médikit, les soins magiques et la récupération naturelle ont des procédures distinctes. Respecter le délai d’intervention, les seuils liés à l’Essence et la limite d’une tentative de chaque type pour un même ensemble de blessures.',topic='personnage',tags=('soigner','healing','first aid','Biotech','blessures'))
R('core',127,'Toxines et drogues','Identifier le vecteur d’exposition, la rapidité, la durée, la Virulence et les effets. Le test de résistance réduit la Virulence avant de déterminer les dommages et états restants. Les protections ne sont utiles que si elles correspondent au vecteur.',tags=('poison','toxin','toxine','antidote'))
R('core',137,'Lancer un sort','Lancer un sort est une action majeure. La cible et le lanceur doivent être présents sur le même plan ; un lien valide dépend de la portée du sort.',steps=('Choisir une cible valide et vérifier la portée : Contact, ligne de vue ou zone.','Choisir les ajustements autorisés, qui peuvent augmenter le Drain.','Effectuer Sorcellerie + Magie et appliquer le seuil ou l’opposition de la description du sort.','Résister au Drain avec Volonté + attribut de tradition.'),topic='magie',kind='action',tags=('spellcasting','sort','sorcellerie'))
R('core',137,'Amplifier un sort et agrandir sa zone','Un sort de combat peut gagner +1 dommage de base pour +2 Drain. Une extension de zone ajoute deux mètres de rayon pour +1 Drain. Le nombre d’ajustements ne peut dépasser le plus haut rang entre Magie et Sorcellerie.',topic='magie',tags=('amplification','rayon','zone','drain'))
R('core',137,'Résister au Drain','Volonté + attribut de tradition : chaque succès réduit le Drain de 1. Dans ce livre français, si les dommages restant après résistance dépassent le rang de Magie, ils sont physiques ; sinon ils sont étourdissants. Le Drain se soigne par récupération naturelle ou par les moyens d’Atout prévus.',topic='magie',tags=('fatigue','hermétique','chaman','drain'))
R('core',137,'Cibles des sorts et ligne de vue','Les sorts mana visent les êtres ayant une composante astrale, pas les objets inanimés. Les sorts physiques peuvent viser êtres et objets sur le plan physique. Des optiques directes peuvent établir une ligne de vue ; une image numérisée ne la remplace pas.',topic='magie',tags=('LOS','LdV','mana','physique'))
R('core',136,'Apprendre un sort ou un rituel','Disposer d’une loge appropriée et d’une formule ou d’un enseignant. L’étude prend une semaine, à raison de huit heures par jour, puis coûte 5 Karma à l’achèvement. Un enseignant peut réduire la durée selon les règles d’Enseignement.',topic='magie')
R('core',180,'Score de Surveillance et Convergence','Les actions illégales et le temps écoulé augmentent le Score de Surveillance selon la procédure matricielle. Atteindre le seuil de Convergence déclenche l’intervention de DIEU. Un accès réussi ne rend pas les actions suivantes invisibles.',topic='matrice',tags=('SS','OS','overwatch','GOD','hacking'))
R('core',181,'Accès matriciel','Distinguer les accès Extérieur, Utilisateur et Administrateur. Chaque action indique son accès nécessaire. Accéder à un PAN ou à un serveur ne signifie pas obtenir tous les droits ; contrôler l’accès avant de choisir le test.',topic='matrice',tags=('user','admin','hacker','piratage'))
R('core',181,'Perception matricielle et mode silencieux','La perception matricielle permet de repérer et d’examiner les icônes. Le mode silencieux nécessite de résoudre l’opposition de détection appropriée : il ne supprime pas automatiquement la présence de l’icône ni la Surveillance.',topic='matrice',tags=('silent running','icone','détection'))
R('core',178,'Attributs matriciels','Attaque, Corruption, Traitement de données et Firewall sont distincts des attributs physiques et mentaux. En anglais, Sleaze correspond à Corruption ; Data Processing à Traitement de données. Conserver l’attribut exigé par chaque action.',topic='matrice',tags=('ASDF','ACDF','attack','sleaze','data processing','firewall'))
R('core',204,'Modes de contrôle des drones','Distinguer les ordres donnés à l’autopilote, le contrôle à distance et l’immersion par câblage de contrôle. Les compétences, attributs, initiatives et logiciels applicables changent avec le mode de contrôle.',topic='rigging',tags=('drone','rigger','RCC','CCR','plonger'))
R('core',210,'Autosofts','Les autosofts fournissent des fonctions aux drones qui agissent avec leur pilote automatique. Leur indice et leur compatibilité comptent ; les bonus d’un rigger immergé ne sont pas automatiquement ceux d’un drone autonome.',topic='rigging',tags=('drone','logiciel','pilote','autosoft'))
R('core',229,'Armure renforcée','Ajouter l’indice au SD. Le même indice fournit des succès automatiques aux tests de résistance aux dommages. Une attaque dont la VD modifiée est inférieure à cet indice n’inflige aucun dommage : aucun jet de résistance n’est alors nécessaire.',topic='creatures',tags=('hardened armor','créature'))
R('core',232,'Immunité aux armes normales','L’Immunité applique l’effet d’une Armure renforcée d’indice Essence/2 contre le type d’attaque concerné. Les armes normales excluent les attaques magiques indiquées par la règle. Consulter le pouvoir pour les exceptions de vulnérabilité et d’allergie.',topic='creatures',tags=('spirit','esprit','immunity'))

# Wild Life: creature handling, costs, commands, training and new powers.
R('wild',176,'Influence : spécialisation Créatures','La spécialisation Créatures s’applique aux tests d’Influence impliquant directement des créatures, notamment l’apprivoisement et le dressage. Une créature consciente utilise les règles sociales ordinaires et ne peut pas être apprivoisée comme un animal.',topic='creatures',original='New Influence Skill Specialization/Expertise: Critters')
R('wild',177,'Intimider une créature','Action majeure : Influence (Intimidation ou Créatures) + Charisme opposé à Volonté + Intuition. Chaque succès net fait reculer la créature un round. Des succès nets au moins égaux à sa Volonté la dissuadent sans limite de durée ; une action hostile met fin à l’effet.',topic='creatures',kind='action',original='Please Don’t Eat Me')
R('wild',177,'Apaiser une créature','Offrir quelque chose qu’elle désire, puis utiliser une action majeure et Influence (Créatures) + Charisme contre Volonté + Intuition. Une offre particulièrement adaptée donne 1 Atout. Chaque succès net achète un round de tolérance ; atteindre sa Volonté rend l’apaisement indéfini. Les interactions suivantes dans l’heure gagnent 1 Atout. Une hostilité annule l’effet et empêche un nouvel apaisement pendant au moins 24 heures.',topic='creatures',kind='action',original='Appeasing a Critter')
R('wild',177,'Nourrir une créature','Les coûts mensuels supplémentaires dépendent du régime et du niveau de vie.',topic='creatures',fields=({'label':'Herbivore / omnivore','value':'CON × 50 ¥ si vie à la rue ou en squat ; couvert dès le niveau Bas.'},{'label':'Carnivore','value':'CON × 100 ¥ aux niveaux Rue, Squat ou Bas ; couvert dès Moyen.'},{'label':'Régime exotique obligatoire','value':'CON × 250 ¥ au niveau Moyen ou inférieur ; couvert dès Élevé.'}))
R('wild',177,'Laisser une créature chasser sa nourriture','Plein air ou Perception + Intuition : chaque succès réduit de 1 sa Constitution pour calculer le coût alimentaire du mois. Atteindre CON couvre toute la nourriture, sans crédit pour les mois suivants. Une complication inflige 6P, résistés avec CON. Un échec critique la fait se perdre ; la retrouver demande par défaut Plein air (Pistage) + Intuition (6, 1 heure), étendu.',topic='creatures',kind='action',original='Forage/Hunt')
R('wild',177,'Famine d’une créature','Un mois sans nourriture diminue la Constitution de 1 ; à 0, la créature meurt. Une alimentation rétablie rend 1 CON par semaine. Un Régime alimentaire obligatoire non satisfait peut tuer en quelques jours : la règle mensuelle ordinaire ne s’applique pas.',topic='creatures',original='Starving Critters')
R('wild',178,'Héberger une créature','À la rue ou en squat, pas de coût de logement spécifique mais pas de lieu sûr. Au niveau Bas, seules les ordinaires de CON 2 ou moins peuvent habiter sur place avec arrangement ; au niveau Moyen, CON 4 ou moins, sans prédateurs dangereux ni créatures Éveillées ou Émergées. Les niveaux Élevé et Luxe permettent davantage, sous réserve des nuisances.',topic='creatures',original='Housing')
R('wild',178,'Niveaux de vie et logement animal','Avec les points de niveau de vie du Companion : Créature à domicile coûte 1 point par créature ordinaire, 2 par Éveillée ou Émergée. Un hébergement séparé coûte 2 points de base, puis 1 par ordinaire ou 2 par Éveillée/Émergée. Ajouter 1 point pour un gardien qui assure les soins courants sans risquer sa vie.',topic='creatures',original='New Lifestyle Qualities')
R('wild',179,'Localiser une créature sauvage','Dans son habitat, effectuer Plein air (Pistage) + Intuition, test étendu d’intervalle quatre heures. Ajouter 1D6 au seuil de base, après son éventuel doublement pour une espèce très rare. Une connaissance adaptée donne 1 Atout à dépenser sur ce test. Remplacer un dé par un dé libre : son résultat de 1 ou 6 provoque une rencontre dangereuse.',topic='creatures',kind='action',fields=({'label':'Ordinaire','value':'Seuil de base 6'},{'label':'Éveillée','value':'8 + MAG, puis encore +MAG si Dissimulation'},{'label':'Émergée','value':'10 + RÉS ; perception de la Résonance nécessaire'}))
R('wild',179,'Pistage animal : complications','Sur complication, les créatures trouvées savent que vous êtes là. Opposer Perception + Intuition à Agilité + Furtivité ; ajouter leur Magie au seuil si elles ont Dissimulation. Si elles échappent au repérage, recommencer le pistage avec un intervalle d’une heure, sans le +1D6 initial. Un échec critique impose de recommencer au seuil de base +2D6 ; chaque nouvel échec critique ajoute encore 1D6.',topic='creatures')
R('wild',180,'Piéger une créature','Prévoir appât et piège. Les collets improvisés conviennent à CON 2 ou moins ; une cage doit avoir un indice au moins égal à CON. Poser et camoufler prend au moins une minute et un test Plein air (Survie) + Intuition. En 2D6 heures la créature rencontre le piège ; ses succès de Perception + Intuition doivent atteindre ceux du poseur pour l’éviter.',topic='creatures',kind='action')
R('wild',180,'Creuser une fosse','Une fosse adaptée demande CON heures à une personne, moitié moins à deux ; pour CON 10 ou plus, trois personnes peuvent diviser la durée par trois. Avec un engin de terrassement, compter CON × 10 minutes.',topic='creatures')
R('wild',180,'Réaction d’une créature attaquée','Le MJ choisit ou lance 2D6 : de 2 à 7, fuite ; de 8 à 12, attaque. Modifier le jet selon son régime, son Éveil ou son Émergence et le rapport numérique.',topic='creatures',fields=({'label':'Herbivore','value':'−2 ; 0 si Éveillé/Émergé'},{'label':'Omnivore','value':'0 ; +2 si Éveillé/Émergé'},{'label':'Carnivore','value':'+2 ; +4 si Éveillé/Émergé'},{'label':'Supériorité numérique des créatures','value':'+2 ; −2 si elles sont moins nombreuses'}))
R('wild',180,'Apprivoiser et dresser','Consacrer au moins une heure quotidienne pendant une semaine. Effectuer Influence (Créatures) + Charisme contre Intuition + Volonté. Toute perte d’Essence donne −1 dé par point entamé ; un critterjack réduit ce malus de son indice. Un échec permet une nouvelle semaine avec −1 dé cumulatif, sauf pause d’au moins une semaine. Une créature libre doit d’abord être apaisée indéfiniment.',topic='creatures',original='Taming the Wild')
R('wild',181,'Acheter une créature','Une créature achetée est apprivoisée mais pas automatiquement dressée. Le prix de base et la disponibilité dépendent de sa nature ; des traits et le dressage les modifient.',topic='creatures',fields=({'label':'Animal domestique ordinaire','value':'CON × 100 ¥ ; disponibilité —'},{'label':'Animal exotique','value':'CON × 250 ¥ ; disponibilité 4'},{'label':'Animal sauvage','value':'CON × 250 ¥ ; disponibilité 4(L)'},{'label':'Éveillé','value':'(CON + MAG) × 2 000 ¥ ; disponibilité (MAG + 1)(L)'},{'label':'Émergé','value':'(CON + RÉS) × 2 000 ¥ ; disponibilité (RÉS + 1)(L)'},{'label':'Traits positifs / négatifs','value':'Disponibilité ±1 par trait ; +1 000 ¥ par Karma net positif ou −5 % par Karma net négatif.'},{'label':'Dressage à l’achat, table de prix','value':'+500 ¥ par ordre ; +750 ¥ par entraînement spécial ; disponibilité +1 chacun.'}),warning='Le paragraphe sur les services de dressage p. 183 donne un autre calcul pour un achat déjà dressé : CON effective +1 par formation et une semaine de délai. Les deux indications du livre sont conservées séparément.')
R('wild',181,'Apprendre et déclencher un ordre','Une créature apprend au maximum LOG × 2 ordres. Chaque nouvel ordre demande une semaine avec une heure par jour et un test de dressage réussi. Son déclencheur doit être perceptible et coûte une action mineure. Un ordre ancien peut être remplacé au même coût d’apprentissage.',topic='creatures',original='Critter Commands')
R('wild',181,'Ordres complexes et compréhension','Ordres multiples simultanés, cible imperceptible ou situation confuse : LOG + INT, seuil 1 ou 2 selon la complexité. Un échec fait revenir la créature auprès de son maître pour attendre des instructions. Un échec critique lui fait exécuter une autre action ou viser une autre cible, sans lui faire adopter un comportement directement autodestructeur.',topic='creatures',original='Comprehension Test')

COMMANDS=[
 (182,'Attaquer, létal ou non létal','Désigner la cible. L’attaque létale et l’attaque non létale nécessitent chacune leur propre ordre ; par défaut la créature utilise généralement son attaque létale la plus puissante.','Attack (Lethal or Non-Lethal)'),
 (182,'Livrer un objet','Donner un objet à porter vers une personne ou un point de dépôt prédéfini, ou vers une cible désignée en ligne de vue.','Deliver'),
 (182,'Rapporter un objet','Désigner l’objet. Il doit être visible, sauf si la créature connaît déjà l’objet et son emplacement ; une récupération sans perception actuelle impose un test de compréhension.','Fetch'),
 (182,'Immobiliser une cible','Cet ordre distinct d’une attaque ordinaire demande à la créature de lutter et de retenir la cible désignée.','Grapple'),
 (182,'Attaque en meute','Réservé aux créatures connaissant Attaquer. Utiliser les groupes de figurants. La meute peut aussi soutenir le maître, attaquant principal : sa réserve et son SO sont alors augmentés selon la taille du groupe.','Pack Attack'),
 (182,'Patrouiller','Apprendre un trajet demande une heure et Influence (Créatures) + Charisme (2). Maximum LOG trajets. Choisir à l’apprentissage si la patrouille attaque ou alerte ; une nouvelle zone exige un nouveau trajet. Une patrouille qui attaque reste bruyante.','Patrol (Attack or Alarm)'),
 (182,'Protéger','La créature reste près d’une personne ou d’un objet et défend sa charge. Elle ne poursuit pas une menace au-delà de la ligne de vue de ce qu’elle protège.','Protect'),
 (182,'Se replier','La créature revient vers son maître, un lieu sûr ou un véhicule désigné. Un signal vocal est souvent nécessaire dans une situation chaotique.','Retreat'),
 (183,'Secourir','Une créature suffisamment forte peut soutenir, tirer ou transporter une victime vers la sécurité. Appliquer un patch exige des appendices capables de le manipuler et le dressage approprié.','Rescue'),
 (183,'Travail d’équipe avec une créature','Un ordre distinct par compétence connue. Il autorise l’assistance uniquement quand un test d’équipe est normalement permis : pas d’assistance aux tests d’attaque, de Combat rapproché ou de Sorcellerie.','Teamwork (Specify a Skill)'),
 (183,'Pister avec une créature','La créature doit connaître Plein air. Une piste olfactive demande une odeur de référence. Elle dirige ou assiste le test Plein air (Pistage) + Intuition ; son assistance donne aussi 1 Atout, perdu s’il n’est pas utilisé sur ce test.','Track'),
 (183,'Faire utiliser un pouvoir','Apprendre un ordre différent pour chaque pouvoir. Le déclencheur précise la cible et l’usage demandé ; posséder le pouvoir ne suffit pas à pouvoir l’exécuter sur commande.','Use Critter Power')]
for page,name,body,en in COMMANDS:R('wild',page,'Ordre : '+name,body,topic='creatures',kind='action',original=en)
R('wild',183,'Entraînements spéciaux','Maximum INT × 2 entraînements, distincts de la limite d’ordres. Chaque formation prend au moins une semaine et une heure quotidienne, puis un test de dressage. Un entraînement existant peut être remplacé lors de l’apprentissage.',topic='creatures',fields=({'label':'Armure','value':'S’habituer à porter une armure.'},{'label':'Augmentations','value':'Exploiter une augmentation nécessitant un dressage.'},{'label':'RA','value':'Comprendre les signaux audio, visuels ou simsens en RA.'},{'label':'Effet magique ou matriciel','value':'Un entraînement par pouvoir, sort ou effet à exploiter.'},{'label':'Territoire','value':'Rester dans un lieu donné et y revenir après un départ forcé ; un seul territoire.'},{'label':'Armes','value':'Utiliser une arme compatible avec son anatomie ou son équipement.'}))
R('wild',184,'Payer un dresseur','Dresseur engagé : réserve Influence du contact × 2, plus sa Loyauté s’il fait partie de vos contacts ; le maître ne peut pas modifier ce jet avec son Atout. Coût hebdomadaire : Influence × 100 ¥. Un assistant ajoute son Influence à votre réserve, pour Influence × 50 ¥ par semaine. Doubler le prix pour les Éveillés, les Émergés ou une Essence inférieure à 5 ; payer même en cas d’échec.',topic='creatures',original='Paid Training Services')
R('wild',184,'Atout et créatures','En général, le maître ne dépense pas ses bonus ou actions d’Atout pour les jets de sa créature, sauf exception telle que le parcours Lien avec une créature. Si la créature gagne un point d’Atout sur une action, elle le dépense immédiatement pour relancer un dé raté.',topic='creatures',original='Edge Actions')
R('wild',184,'Tous sur la cible','Action mineure Commander une créature. Coût : 1 Atout par créature qui ne connaît pas Attaque en meute ; toutes doivent connaître Attaquer. Elles attaquent ensemble une cible à la fois, comme un groupe.',topic='creatures',kind='action',original='Dogpile')
R('wild',184,'Connexion instinctive','Coût : 4 Atout. Utiliser Influence pour tenter d’apaiser une créature sans lui proposer de nourriture ou autre chose qu’elle désire.',topic='creatures',kind='action',original='Instinctive Connection')
R('wild',184,'Ordre improvisé','Coût : 2 Atout et une action majeure. Influence (Créatures) + Charisme (3), avec remplacement d’un dé par un dé libre, pour faire exécuter un ordre non appris. Appliquer le malus de perte d’Essence et la réduction du critterjack.',topic='creatures',kind='action',original='Improvised Command')
R('wild',184,'Attention !','Coût : 2 Atout et une action mineure libre. Lorsqu’une créature est attaquée, ajouter son rang d’Athlétisme à sa réserve de défense grâce à votre avertissement.',topic='creatures',kind='action',original='Look Out!')
R('wild',184,'Partager l’effet','Coût : 4 Atout et une action mineure Commander une créature. Transformer un pouvoir à cible unique en zone de rayon deux mètres ; +1 Atout par deux mètres supplémentaires. Chaque cible gagne 1 Atout pour résister à cet effet affaibli.',topic='creatures',kind='action',original='Spread the Love')

QUALITIES=[
 (185,'Créature futée','2 Karma. Le seuil des tests de compréhension baisse de 1, avec un minimum de 1.','Clever Critter'),
 (185,'Désireuse de plaire','2 Karma, ou 1 pour un chien. Pour résister au dressage, seuls ses 6 comptent comme succès. Les tests d’Influence visant à lui donner des ordres ont leur seuil réduit de 1.','Eager to Please'),
 (185,'Exceptionnelle','5 Karma. Une seule fois, lors de l’acquisition : augmenter un attribut ou une compétence de 1.','Exceptional'),
 (185,'Peu exigeante','1 Karma. Pour les frais mensuels de nourriture et de logement, compter la moitié de sa CON, arrondie au supérieur.','Low Maintenance'),
 (185,'Réceptive au dressage','3 Karma par niveau, maximum égal au plus petit de LOG et INT. Chaque niveau autorise un ordre et un entraînement spécial supplémentaires.','Receptive to Training'),
 (185,'Trop mignonne','2 Karma. Métahumains et créatures conscientes ne peuvent gagner ou dépenser d’Atout sur un test susceptible de la blesser directement. L’effet cesse pour un individu qu’elle attaque ou vise avec un pouvoir hostile.','Too Cute'),
 (186,'Vigilante','3 Karma. Achète ses succès de Perception à raison d’un succès pour trois dés. Sur un test de surprise, gagne 1 Atout réservé à ce test.','Vigilant'),
 (186,'Âme sauvage','1 Karma. Ajouter un dé libre à ses tests de compétence. Une complication ou un échec critique la fait désobéir et fuir au moins une heure, sauf apaisement comme pour un animal sauvage. Une créature apprivoisée reçoit ce trait, équilibré par un trait négatif.','Wild Soul'),
 (186,'Désobéissante','Bonus 4 Karma. Aucun gain ou usage d’Atout pour les tests d’Influence visant à interagir avec elle.','Disobedient'),
 (186,'Méfiante','Bonus 3 Karma. Chaque dépense d’Atout pour ses tests ou une action d’Atout l’affectant coûte un point supplémentaire.','Distrustful'),
 (186,'Frénésie sauvage','Bonus 5 Karma. Continue d’attaquer après la défaite des ennemis, puis vise l’être le plus proche. La calmer demande une action majeure et Influence (Créatures) + Charisme contre VOL + INT. Nécessite une arme naturelle ou un pouvoir infligeant des dommages.','Feral Frenzy'),
 (186,'Très exigeante','Bonus 1 Karma par niveau, maximum 3. Ajouter le niveau à CON uniquement pour calculer les coûts mensuels de nourriture et de logement.','High Maintenance'),
 (186,'Jalouse','Bonus 2 Karma. En présence d’autres créatures, donner un ordre coûte deux actions mineures. Attaque en meute et Tous sur la cible sont indisponibles.','Jealous'),
 (186,'Pacifique','Bonus 2 Karma. Aucun gain ou usage d’Atout pour ses jets de combat. Nécessite une arme naturelle ou un pouvoir causant des dommages.','Lover, Not a Fighter'),
 (187,'Privée de pouvoir','Bonus 3 Karma. Retirer un pouvoir de créature. Le trait peut être pris plusieurs fois, pour des pouvoirs différents.','Powerless'),
 (187,'Avorton','Bonus 4 Karma. Ignorer un succès à chaque test de Constitution pour résister aux dommages.','Runt'),
 (187,'Indressable','Bonus 2 Karma par niveau. Chaque niveau retire un ordre et un entraînement spécial à ses capacités d’apprentissage, minimum zéro.','Untrainable')]
for page,name,body,en in QUALITIES:R('wild',page,'Trait de créature : '+name,body,topic='creatures',original=en)

R('wild',185,'Traits des compagnons animaux','Ces traits concernent les créatures apprivoisées et dressées, pas les métahumains ni les créatures conscientes. Une créature achetée peut avoir au maximum six traits. Avec Amélioration permanente du parcours de lien, les Karma des traits négatifs admissibles réduisent le coût positif avant le doublement du coût à payer par le maître.',topic='creatures',original='Critter Companion Qualities')
R('wild',187,'Harnais et armures pour créatures','Un harnais transporte un objet par point de CON ; avec CON 2 ou moins, uniquement de très petits objets, et les grands objets exigent CON 6 ou plus. Le matériel adapté coûte 10 % de plus, disponibilité +1.',topic='creatures',fields=({'label':'Harnais','value':'SD — ; capacité 4 ; disponibilité 2 ; CON × 50 ¥.'},{'label':'Armure légère','value':'SD +2 ; capacité 6 ; disponibilité 3 ; CON × 100 ¥. Sans entraînement, donner un ordre exige une action majeure.'},{'label':'Armure lourde','value':'SD +4 ; capacité 8 ; disponibilité 4 ; CON × 200 ¥. Interdit vol et nage ; sans entraînement, Entravé et ordres en action majeure.'},{'label':'Armure renforcée pour créature','value':'SD +6 ; capacité 8 ; disponibilité 6(L) ; CON × 1 000 ¥. +4 dés de résistance avec CON et 2 succès automatiques. Sans le second entraînement approprié : Immobilisé ; même entraînée : Entravé, sans vol ni nage.'}),warning='Le +6H de la table n’est pas remplacé par l’intégralité du pouvoir Armure renforcée : la description donne ici ses effets précis.')

POWERS=[
 (188,'Coloration adaptative','Physique, automatique, personnelle, permanente. Confère Invisible (supérieur) d’indice MAG à l’arrêt ; en mouvement, indice divisé par deux, arrondi à l’inférieur, minimum 1. Le SO des attaques à distance contre la créature baisse de 2. Affecte vision normale et thermographique, pas les sens non visuels sauf exception du profil.','Adaptive Coloration'),
 (188,'Inhibition arcanique','Mana, action majeure, LdV. Crée un vide de mana temporaire de rayon MAG/2. Il dure autant de rounds que les succès nets d’un test MAG + CON (4).','Arcane Dampening'),
 (189,'Parallélisme RA','Physique, action mineure, LdV, maintenu. Perçoit simultanément monde physique et virtuel, comme avec la RA, sans malus de distraction.','AR-Parallelism'),
 (189,'Se fondre dans la Matrice','Physique, action mineure, personnelle, maintenue. La créature passe en mode silencieux et reçoit +2 dés pour s’opposer aux tests de perception matricielle visant à la repérer.','Blend'),
 (189,'Cécité','Physique, action majeure, LdV, maintenue. AGI + MAG contre VOL + LOG. Un succès net impose Aveuglé I ; deux nets, Aveuglé II ; quatre nets, Aveuglé III.','Blindness'),
 (189,'Porteuse saine','Physique, automatique, personnelle, permanente. Transporte une maladie sans en souffrir. Les contacts non protégés avec ses fluides peuvent la transmettre ; appliquer les tests de résistance à cette maladie.','Carrier'),
 (189,'Robuste','Physique, automatique, personnelle, permanente. Ajouter l’indice du pouvoir au Moniteur d’état physique. Conserver la valeur imprimée du profil lorsqu’elle intègre déjà ce bonus.','Durable'),
 (189,'Empathie','Mana, automatique, LdV, permanente. Ajouter MAG aux réserves de tous les tests d’Escroquerie et d’Influence.','Empathy'),
 (189,'Drain d’énergie : Magie','Mana, action majeure, Contact. Cible un Éveillé non astral consentant ou maîtrisé ; une résistance physique active empêche le drain. Test étendu CHA + MAG (5 − MAG, 1 minute), tel qu’imprimé dans la source : retirer 1 MAG à la victime et l’ajouter à la créature, sans dépasser son maximum naturel. Le maximum de MAG de la victime ne baisse pas et le point peut être racheté en Karma. Fatigué augmente avec les points drainés. Une interruption empêche le drain.','Energy Drain (Magic)'),
 (189,'Euphorie','Physique, action mineure, Contact, maintenue. CHA + MAG contre VOL + LOG : la cible devient Immobilisée et subit un malus de réserve égal aux succès nets. À son tour, une action majeure et VOL + LOG contre le seuil des succès nets permettent de se libérer. Ensuite, tester la dépendance contre une Puissance égale à MAG de la créature.','Euphoria'),
 (190,'Fragile','Physique, automatique, personnelle, permanente. Réduire le Moniteur d’état physique de l’indice indiqué. Ne pas retirer une seconde fois cet indice si le moniteur fourni dans le profil en tient déjà compte.','Fragile'),
 (190,'Conscience collective','Mana, automatique, permanente. Les membres partagent esprit, perceptions et coordination. Ils peuvent s’entraider pour les tâches compatibles ; employer les groupes de figurants pour simplifier. Portée propre au profil, ligne de vue par défaut.','Gestalt Consciousness'),
 (190,'Dissimulation holographique','Physique, action majeure, personnelle, maintenue. Dans une zone riche en RA, appliquer −RÉS aux tests de Perception pour voir la créature, et −2 dés aux attaques à distance contre elle. Sans connexion matricielle active ni perception de la RA, la cible n’est pas affectée.','Holographic Concealment'),
 (190,'Chant hypnotique','Mana, portée spéciale, maintenu. MAG + MAG contre VOL + LOG. Chaque tranche de deux succès nets déplace d’un niveau l’attitude envers le sujet choisi : Hostile, Antipathique, Neutre, Amical. Le pouvoir change l’attitude sans commander les actions. La table anglaise indique une action « Complex », terminologie conservée comme ambiguïté de la source.','Hypnotic Song'),
 (190,'Sens de la magie','Mana, automatique, personnelle, permanent. Détecte la présence d’une magie ayant une Puissance ou un Drain à moins de MAG × 10 mètres, sans en déterminer la nature ni la direction.','Magic Sense'),
 (190,'Puits de mana','Mana, action majeure, personnelle, maintenue. Crée un flux de mana faible dans un rayon de deux mètres. Le profil précise une éventuelle orientation vers une tradition.','Mana Well'),
 (190,'Mutation','Mana, action majeure, personnelle, spéciale. Transformations et nouvelles capacités selon le profil. Une mutation à la fois ; plusieurs peuvent se succéder, sans dépasser le plus grand de l’Essence et de la Magie. Elles sont généralement temporaires et liées à un déclencheur.','Mutation'),
 (190,'Déphasage','Physique, action majeure, personnelle, maintenue. Traverse la terre naturelle à sa vitesse normale. Le pouvoir n’accorde pas de vision à travers le sol et ne traverse pas les matériaux construits comme béton, brique, métal ou plastique.','Phasing'),
 (191,'Engloutissement radioactif','Physique, action majeure, Contact, maintenu. Attaque de Combat rapproché, VD MAG P augmentée des succès nets ; cible Immobilisée et Irradiée. À son tour, la victime peut dépenser une majeure pour opposer Athlétisme + FOR à CON + MAG. Si elle reste prisonnière, elle subit de nouveau MAG P au prochain tour de la créature, avec résistance normale.','Radiation Engulf'),
 (191,'Alimentation de Résonance','Physique, automatique, personnelle, permanente. +1 dé aux tests de Perception ou Traquer une icône contre des êtres ou appareils sans fil. Le bonus passe à +2 pour IA ou RÉS ≥4, puis +3 à partir de 7.','Resonance Feed'),
 (191,'Forme de sable','Physique, action majeure, personnelle, maintenue. Transformation et retour prennent chacun une majeure, avec les objets non vivants transportés. Déplacement cinq mètres par action, environ 6 km/h. Passe dans les fissures non étanches mais pas les protections contre gaz, microbes ou particules fines. Immunité aux armes normales ; une substance allergène ou vulnérable force le retour. Aucun autre pouvoir utilisable sous cette forme.','Sand Form'),
 (191,'Projection sonique','Physique, action majeure, LdV, instantanée. Attaque à distance MAG + AGI, VD MAG P, SO 2×MAG / 2×MAG−2 / 2×MAG−8 / 2×MAG−10. Une portée dont le SO est nul ou négatif est inaccessible. La cible devient aussi Assourdie I et Désorientée pendant MAG rounds.','Sonic Projection'),
 (191,'Attaque sonique sous l’eau','Augmenter la VD de moitié, arrondie à l’inférieur, avec un ajout minimal de 1, et le SO de 2. Les êtres à trois mètres de la cible reçoivent les états de l’attaque sans jet de résistance aux dommages. Être touché impose Assourdi I et Désorienté ; subir des dommages impose Assourdi II, Désorienté et Figé. Figé devient Entravé à la fin du round suivant.','Sonic Attacks in Water'),
 (191,'Spores','Physique, action majeure, portée et durée spéciales. Résister comme à une toxine de Puissance 2 × Essence. Vecteurs usuels : Contact, Ingestion, Inhalation. Chaque succès réduit la Puissance ; à zéro, pas d’effet. Tant que la contamination n’est pas nettoyée, un nouveau contact provoque une exposition à la moitié de la Puissance initiale.','Spores'),
 (192,'Souillure','Mana, action majeure, personnelle, spéciale. Une créature toxique pollue le mana dans un rayon de deux mètres. Utiliser la procédure de Purification de Street Wyrd, avec +1 au flux toxique par tranche de deux succès nets de la créature. La procédure complète de ce supplément externe n’est pas présente dans les six ouvrages fournis.','Taint'),
 (192,'Perception des vibrations','Physique, automatique, personnelle, permanente. Perception + INT permet de sentir un mouvement du sol, même dans le noir, à INT mètres. Ne donne ni localisation exacte ni détection d’un être immobile.','Tremor Sense'),
 (192,'Marche murale','Physique, automatique, personnelle, permanente. Marche normalement sur les murs et plafonds sans test spécial. Pour un sprint, la source demande d’utiliser Escalade plutôt que Course.','Wall Walking')]
for page,name,body,en in POWERS:R('wild',page,'Pouvoir : '+name,body,topic='creatures',original=en)
R('wild',192,'Irradié : nouvel état','Au début de chaque jour, résister à des dommages physiques égaux à l’indice. Si des dommages passent, devenir aussi Nauséeux. Indice non précisé : MAG de la créature. Une complication augmente les dommages de 1 ; un échec critique réduit le maximum de CON de 1. Un traitement médical en établissement réduit l’indice de 1, pour 500 ¥ ou avec un contrat DocWagon Or ou supérieur.',topic='creatures',original='Irradiated #',tags=('radiation','irradiation','état'))

# Sixth World Companion: these options must not silently override core rules.
def C(page,title,body,original,**kwargs):R('companion',page,title,body,topic=kwargs.pop('topic','variantes'),optional=True,original=original,**kwargs)

C(144,'Atout réinitialisé à chaque scène','Ramener la réserve d’Atout à sa valeur de départ au début de chaque scène, au lieu d’attendre une nouvelle séance.','Faster Edge Resets')
C(144,'Gains d’Atout augmentés','Autoriser jusqu’à trois points d’Atout gagnés par test. Le maximum conservé reste de sept. Cette option remplace la limite de gain normale.','Higher Edge Gains')
C(144,'Banque d’Atout','Placer l’Atout qui dépasserait la limite de gain dans une réserve commune. Un allié peut l’utiliser en dépensant une action mineure libre. Les points non utilisés disparaissent en fin de round.','Edge Banking')
C(145,'Avantage cumulatif du SO contre le SD','Un avantage de +8 dans la comparaison SO/SD peut accorder deux points d’Atout, au lieu du seul point accordé à partir de +4. Maximum deux points issus de cette comparaison. L’option couvre aussi les comparaisons matricielles, magiques et sociales correspondantes.','Stacking Advantage')
C(145,'Rééquilibrer les traits qui donnent de l’Atout','Pour un trait coûtant moins de 8 Karma et donnant de l’Atout, limiter le gain aux tests de compétence ; les points gagnés sont perdus s’ils ne sont pas utilisés sur le test concerné.','Rebalanced Edge Qualities')
C(145,'Transformer l’Atout en dés','Chaque point accordé peut devenir +1 dé pour l’action ; avec accord du MJ, il peut plutôt imposer −1 dé à l’opposition si l’avantage est relatif à elle. Le point reste compté dans le plafond de gain. Une action d’Atout peut aussi être payée par −1 dé par point de coût, ce qui consomme l’unique usage d’Atout de l’action.','Edge As Dice Pool Modifications')
C(145,'Atout simplifié','Le MJ évalue globalement les avantages à chaque round au lieu de recalculer chaque composante à chaque action. L’équipe avantagée reçoit un ou deux points d’Atout par membre et par round ; réévaluer quand les circonstances changent.','Streamlined Edge')
C(145,'Traverser de part en part','Action d’Atout avec munitions standard, sans étui ou APDS. Augmenter la VD de l’arme, modifications de munitions comprises, de moitié arrondie au supérieur. Coût : CON de la cible ; les APDS diminuent ce coût de 2, minimum 1.','Through and Through',kind='action')
C(145,'Choke de shotgun','À portée proche ou courte, une cartouche de fléchettes peut produire une rafale large BF même si le shotgun n’a pas ce mode. Coût : 2 Atout, ou 1 avec smartgun.','Shotgun Choke',kind='action')
C(145,'Élimination silencieuse','Attaque de mêlée contre un figurant à portée qui ignore totalement votre présence : compétence de l’arme + AGI (4). Une réussite remplit son moniteur. Coût d’Atout égal au Professionnalisme, minimum 1 ; être simplement invisible ne suffit pas.','Silent Takedown',kind='action')
C(145,'C’est un pétard mouillé !','Après la résolution de la déviation, dépenser 5 Atout pour annuler la détonation et les effets d’une arme explosive.','It’s A Dud!',kind='action')
C(146,'Premiers soins aux augmentés','Pour des premiers soins ou un médikit avec spécialisation Biotechnologie ou Cybertechnologie, utiliser comme seuil l’Essence arrondie à l’inférieur. Les médikits bénéficient aussi de l’option. La limite d’une tentative par ensemble de blessures reste applicable.','First Aid for the Augmented')
C(146,'Le bioware guérit naturellement','Déduire l’Essence dépensée en bioware des seuils de soins fondés sur l’Essence. Exemple de la source : seuil normal 5 − Essence 1 = 4 ; avec 2,5 d’Essence de bioware, le seuil devient 1,5.','Bioware Heals Naturally')
C(146,'Surplus de dommages plus meurtrier','Après des dommages de surplus non immédiatement mortels, le personnage meurt dans CON rounds s’il n’est pas stabilisé. Soigner au moins une case de surplus le stabilise, tout comme l’usage d’Atout évitant la mort. De nouveaux dommages de surplus relancent le compte à rebours.','Increased Overflow Lethality')
C(146,'Saignement','Recevoir plus de cases physiques après résistance que sa CON impose Saignement : une case physique non résistée à chaque fin de round. Tout soin ou traumapatch l’arrête. Sinon Biotech + LOG (4, 1 round), étendu ; seuil +2 sans matériel. Cette intervention ne soigne pas les cases et ne consomme pas la tentative de premiers soins.','Bleeding')
C(146,'Niveau de vie et guérison','Modificateur de récupération naturelle : Rue −2 dés, Squat −1, Bas 0, Moyen +2, Élevé +4, Luxe +6. À la rue, la guérison devient un test étendu d’intervalle un jour. Une hospitalisation coûte 500 ¥ par jour et donne les avantages du niveau Moyen, sous réserve de la couverture DocWagon.','Lifestyle and Healing')
C(148,'La magie respecte le libre arbitre','La magie ne peut forcer un être à commettre ou subir une violence ; elle ne peut pas non plus affecter son libre arbitre pendant qu’il est témoin de violence.','Magic Can’t Affect Free Will')
C(148,'Passages pour les esprits','Un esprit doit trouver un milieu adapté à son type pour se matérialiser ; surface minimale de 0,25 m² par point de Puissance, sauf précision. Il peut ensuite se déplacer librement. S’il retourne dans l’astral, un nouveau passage est nécessaire pour revenir. La manifestation intangible reste possible sans passage.','Spirit Doorways')
C(149,'Préparations alchimiques accélérées','L’étape 3 de création d’une préparation ne prend plus que cinq minutes. Les autres coûts et procédures ne sont pas modifiés par cette seule option.','Faster Alchemical Preparation Time')
C(149,'Variante de l’adepte mystique','À la création, chaque point de Magie affecté aux pouvoirs donne 0,5 point de pouvoir. Chaque augmentation ultérieure de MAG donne aussi 0,5 point, y compris pendant la création. En échange : ni Conjuration ni Enchantement, pas de projection astrale et perception astrale uniquement via le pouvoir d’adepte.','Alternate Mystic Adept')
C(149,'Magiciens spécialisés améliorés','Enchanteur : préparer jusqu’à MAG exemplaires identiques sans temps supplémentaire, même Efficacité, mais Drain et réactifs séparés. Sorcier : un réactif peut donner un succès automatique de résistance au Drain de sort. Invocateur : même avantage sur le Drain de Conjuration. Maximum un réactif pour ces succès automatiques.','Enhanced Aspected Magicians')
R('companion',149,'Sorts initiaux d’un enchanteur spécialisé','Clarification officielle présentée comme telle par le Companion : l’enchanteur connaît deux sorts par point de Magie déterminé par sa priorité, comme les autres magiciens lanceurs de sorts, mais ne peut les utiliser que pour l’Enchantement.',topic='magie',original='Enchanters’ Known Spells During Character Generation')
C(149,'Le couvert protège des explosions','Réduire la VD d’une explosion de deux fois le niveau de couvert, mesuré par rapport à l’explosion. Sans couvert, être À terre réduit la VD de 2 aux deux premières zones. Cette réduction prolonge Se jeter par terre et ne se cumule pas avec cette action.','Cover Shields Blasts')
C(149,'Éviter plusieurs explosions','Action mineure libre après la déviation : Réaction + Athlétisme − malus d’esquive. Se déplacer d’un mètre par succès et éventuellement se jeter au sol. Si un déplacement, sprint ou évitement a déjà eu lieu ce round, aller directement à l’opposé du centre ou vers le couvert le plus proche si cette option est active. Une utilisation par explosion.','Alternate Avoid Incoming Action',kind='action')
C(150,'APDS améliorées','Diviser par deux, arrondi à l’inférieur, la Structure des barrières et l’indice des effets réduisant la VD, notamment Armure renforcée et celle issue d’Immunité aux armes normales.','Improved APDS')
C(150,'Armes antivéhicules plus meurtrières','Désigner une unique cible primaire : barrière, véhicule ou drone au moins de taille moto, ou créature de CON 10 ou plus. Si elle se trouve au point zéro après déviation, elle subit deux fois la VD de cette zone. Les autres cibles subissent les effets normaux.','More Lethal Anti-Vehicular Rockets and Missiles')
C(150,'Explosions des canons d’assaut','Les munitions de canon d’assaut donnent une attaque explosive : point zéro 6P, zone suivante 4P, pas de zone supplémentaire, rayon 3 m. Le canon peut aussi tirer des munitions standard ou APDS au tarif mitrailleuse ; celles-ci ne provoquent pas d’explosion.','Assault Cannon Blasts')
C(150,'Cumul du suprathyroïdien','Les bonus de la glande suprathyroïdienne échappent aux restrictions de cumul des autres augmentations. Le maximum augmenté des attributs s’applique toujours.','Suprathyroid Bonuses Stack')
C(150,'L’armure convertit des dommages physiques','Après résistance, convertir une case physique en étourdissante par tranche complète de 8 SD, ou de 4 SD contre une explosion. Ne s’applique ni aux toxines ni aux états. Une cible directement touchée par une arme antivéhicule n’en bénéficie pas si l’option antivéhicule correspondante est active.','Armor Lessens Physical Damage')
C(150,'Encaisser le coup','Action mineure libre : contre une attaque physique ou magique infligeant des dommages, utiliser SD comme réserve de défense, avec un dé remplacé par un dé libre. Sur complication ou dé libre à 1, le MJ choisit une armure, augmentation ou pièce d’équipement qui casse et cesse de fonctionner jusqu’à réparation.','Absorb The Blow ([A] Minor Action)',kind='action')
C(151,'Force plutôt qu’Agilité en mêlée','À mains nues ou avec une arme reposant sur masse et élan, utiliser FOR à la place d’AGI pour l’attaque. Ajouter alors AGI au SO à la place de FOR. Si l’arme s’y prête, la tenir à deux mains pour bénéficier de toute la force ; pas de malus de main non directrice.','Rolling Strength Instead of Agility In Close Combat')
C(151,'Force élevée et dommages de mêlée','FOR 7 ou plus : +1 VD ; FOR 10 ou plus : +2 VD. Pas de bonus pour les armes qui n’en bénéficient pas, comme le fouet monofilament, ni pour le pouvoir Arme naturelle. L’option permettant d’attaquer avec FOR reste distincte.','High Strength Adds to Damage')
C(151,'Force élevée et recul','Réduire les malus de SO dus au mode de tir de 1 avec FOR ≥7, de 2 avec FOR ≥10. L’arme doit être contrôlée à deux mains, sans malus de main non directrice.','High Strength Reduces Recoil')
C(151,'Actions de couverture','Retarder des actions d’initiative jusqu’avant son prochain tour, avec déclencheur et action annoncés précisément. Elles sont ensuite traitées comme libres, généralement après l’action du personnage actif, sauf interruption cohérente décidée par le MJ. L’initiative ne change pas ; les actions ne se renouvellent pas au début du tour.','Overwatch Actions')
C(152,'Combat à deux armes','Une mineure Attaque double accompagne la majeure Attaquer contre une cible unique. Désigner l’arme primaire pour VD, type et SO. La secondaire ajoute +1 SO et +1 VD, ou +2 VD si sa VD atteint 5. Si les compétences diffèrent, prendre la moyenne des rangs, arrondie à l’inférieur. Pas d’explosifs ; pas de dépense d’Atout sans Ambidextrie. Les modes de tir appliquent leurs malus aggravés à chacune des armes.','Dual Wielding')
C(152,'Jusqu’à six actions mineures','Le plafond d’actions mineures conservées au début de son tour devient six. Cette option évite de perdre la sixième générée par cinq dés d’initiative si elle n’a pas été utilisée avant le début du tour. Vérifier le plafond déjà retenu par votre édition française.','Up To Six Minor Actions')
C(152,'On n’esquive pas les balles','Remplacer le test opposé d’attaque par un test simple. Seuil de base : 0, plus 1 par tranche complète de six dés de la défense habituelle. Chaque catégorie de portée au-delà de la première ajoute 1, maximum +4 à l’extrême. Le couvert ajoute son niveau ; À terre donne +1 au seuil à moyenne portée ou au-delà, et −1 à la première portée. Les succès au-delà du seuil augmentent la VD. Les actions défensives et la taille modifient aussi le seuil : voir le tableau de la source.','You Can’t Dodge Bullets')
C(153,'Bruit alternatif : parasites et service','Séparer pollution publicitaire, qualité de service et brouillage. Les parasites légers donnent −1 dé matriciel, les moyens +1 aux coûts d’Atout, les forts interdisent gain et dépense d’Atout matriciel. Service faible : −1 dé ; intermittent : seulement des appareils en ligne de vue physique ; absent : connexion directe exigée. Une liaison satellite ramène les deux derniers à un service faible. Chaque réduction de bruit de 2 abaisse les parasites ou le manque de service d’un niveau.','Alternate Noise')
C(153,'Bruit alternatif : brouillage','Brouillage et contre-mesures donnent −1 dé matriciel par niveau. Si leur niveau dépasse l’indice d’un appareil affecté, il ne peut plus contribuer aux actions matricielles ni fournir de bonus sans fil. Les réductions de bruit fonctionnent normalement contre le brouillage et la distance.','Jamming/ECM')
C(154,'Intervalles de vitesse moins pénalisants','Les malus d’intervalle de vitesse ne s’appliquent qu’aux tests d’accident. Les autres tests d’utilisation d’un véhicule ou drone ne les subissent plus.','Less Punitive Speed Interval Penalties')
C(154,'Répéter un plan','Construire une maquette adaptée à des renseignements actuels, ou une simulation en RV avec les ressources d’un niveau de vie Élevé. S’entraîner quarante heures réparties sur dix jours consécutifs au maximum. Lancer la compétence pratiquée + VOL ; ses succès donnent des dés supplémentaires pour l’obstacle ou la tâche répétés. Les avantages durent cinq jours après l’entraînement. Un meneur peut diriger avec Influence (Leadership) + CHA mais ne s’entraîne pas en même temps.','Practice Makes Perfect')
C(154,'Compétences sans plafond après la création','Supprimer le plafond arbitraire de rang en compétence après la création. Le temps d’apprentissage et le Karma restent nécessaires. Cette option ne s’applique jamais à la création du personnage.','Unrestricted Skill Ranks')
C(154,'Spécialisations étendues','Autoriser plusieurs spécialisations dans une compétence, sans devoir acheter d’abord une expertise. La limite d’une expertise par compétence reste applicable.','Expanded Specializations')
C(154,'Réflexes trop nerveux','Les dés d’initiative supplémentaires dus aux augmentations deviennent autant de dés de malus aux tests sociaux, de crochetage et de précision délicate. Une mineure peut désactiver puis réactiver une augmentation non issue de drogues ; tant qu’elle est coupée, elle ne donne ni son bonus ni ce malus.','Twitchy Wires')
C(154,'Échanger du Karma et des nuyens','Une semaine de repos permet d’échanger 1 Karma contre 2 000 ¥ en travaillant pour les corpos, ou 2 000 ¥ contre 1 Karma en aidant les gens. Une variante pour trafiquants d’organes permet jusqu’à 3 Karma à 4 000 ¥ chacun, réservés aux augmentations.','Working for the Man/People/Organleggers')
C(155,'Dépendance aux drogues','Dès la deuxième prise en deux semaines, tester à la fin des effets : CON + VOL contre une réserve de Puissance de la drogue +1 par test déjà fait dans les deux dernières semaines. L’opposition achète ses succès ; une égalité profite au personnage. Un échec donne Dépendance ou augmente son niveau. Surcoût de vie : le plus grand de 5 % ou 100 ¥, par niveau.','Drug Addictions')
C(155,'Se sevrer','Option rapide : rester abstinent Puissance × 2 jours, puis racheter entièrement le trait à 4 Karma par niveau. Option graduelle : Puissance jours d’abstinence et 4 Karma pour diminuer le niveau de 1. Les activités sans Puissance spécifique utilisent 5 par défaut, sous réserve du tableau des vices.','Kicking the Habit')
C(155,'Vérification détaillée des SIN','Opposer l’indice du faux SIN à celui du vérificateur. Le système gagne les égalités ; le texte prévoit aussi, en cas d’égalité, un interrogatoire à réussir avec Escroquerie + CHA au seuil de son indice. À partir de l’indice 5, présenter les échantillons biométriques compatibles demande Furtivité (Escamotage) + AGI contre Perception + INT de l’opérateur.','Expanded Sins and Licenses')
C(156,'Variantes du trait Détenteur de SIN','SIN national, corporatiste ou criminel : 8 Karma. SIN corpo : réputation −10 auprès des Ombres. SIN criminel : réputation −10 auprès des autorités et citoyens respectueux des lois ; +3 points de contacts à la création. Tous les SIN donnent +1 aux vérifications d’augmentation de Pression. Rachat éventuel : coût ×3 pour national/corpo, ×4 pour criminel, avec accord du MJ.','Alternate SIN Qualities')
C(157,'Disponibilité et achats enregistrés','Achat légal sur la Matrice : livraison en Disponibilité jours ; +10 % au prix réduit ce délai de deux jours. Si une licence est nécessaire, opposer son indice à la Disponibilité ; échec : compte suspendu sept jours. Achat clandestin : contact approprié, commission de 10 %, Influence et Loyauté chacune au moins égales à la Disponibilité.','Not Available Here')
C(157,'Défendre une interaction avec sa compétence sociale','La cible d’Escroquerie ou d’Influence peut remplacer un attribut de sa défense par son rang en l’une de ces compétences, spécialisation ou expertise pertinente comprise.','Opposed Social Skills')
C(157,'Argument et contre-argument','Résoudre d’abord le test social opposé normal, puis permettre à l’autre camp de répondre avec sa propre Escroquerie ou Influence. La différence entre les succès nets des deux échanges donne le résultat final du camp gagnant.','Point And Counterpoint')
C(157,'Moniteur d’état social','Moniteur : 8 + VOL/2 arrondie au supérieur. Chaque ligne remplie donne −1 dé aux tests sociaux. Initiative physique sociale : LOG + INT +1D6, sans réflexes augmentés ; un round dure par défaut une minute. Attaque : Escroquerie ou Influence contre la défense appropriée ; les figurants ajoutent leur Professionnalisme en défense.','The Social Condition (Monitor)')
C(158,'Dommages et récupération sociaux','Le vainqueur d’un échange inflige 2 + succès nets, résistés avec VOL. En cas d’égalité, chaque camp résiste à 2. À la fin de l’affrontement, la différence des cases subies détermine les succès nets finaux. Un moniteur partiellement rempli se vide en quittant la scène ; un moniteur plein demande huit heures de repos. Les limites personnelles des personnages ne disparaissent pas avec une victoire sociale.','Social Damage and Recovery')
C(158,'Manœuvres sociales','Club de débat philosophique coûte 5 Karma et donne accès aux actions sociales. Une mineure peut ajouter +1 VD d’attaque verbale ; Escroquerie + LOG (3) et une mineure peuvent imposer −3 dés à la défense adverse. Les actions d’Atout Ne me manipule pas et Fausse équivalence coûtent 4 : ajouter respectivement CHA à la défense contre un argument logique, ou LOG à une tentative sociale fondée sur CHA.','Social Maneuvers')
C(160,'Tactiques téméraires','Une action mineure permet d’ajouter un dé libre au prochain test. Le texte dit ici « ajouter » : cette option particulière est distincte du remplacement d’un dé utilisé dans la présentation générale du dé libre.','Reckless Tactics',kind='action')
C(160,'Dé libre et ajustement de sort','Lors d’une amplification ou d’une extension de zone, une mineure peut ajouter un dé libre au test de Sorcellerie. Les risques et effets du dé libre s’appliquent.','Spell Adjustments',kind='action')
C(160,'Dé libre sans compétence','Une mineure peut ajouter un dé libre à un test de compétence effectué sans entraînement. Cette option n’autorise pas un test normalement impossible sans compétence.','Untrained Skill Tests',kind='action')

R('feu',85,'Mettre en œuvre une tactique d’escouade','Au moins un membre doit connaître Tactiques d’escouade et posséder Influence. Le leader fait Influence + LOG au seuil de la manœuvre ; les participants réservent une majeure pour son tour. Si tous connaissent Tactiques d’escouade, les manœuvres deviennent mineures. Dépasser le seuil de deux succès donne 1 Atout de situation à attribuer par le leader. Les effets se réalisent à la plus basse initiative du groupe.',tags=('TE','leadership','manœuvre','tactique'))
R('feu',85,'Tactique : Flanquer','Seuil 3. Une unité couvre l’ennemi pendant qu’une autre le déborde. Réussite : +2 SO aux participants, −2 SD à la cible. Si l’unité qui déborde approche sans être repérée, la source augmente son bonus de SO de +3.',kind='action')
R('feu',85,'Tactique : Formation en diamant','Seuil 2. Organiser une observation à 360 degrés, généralement à quatre. Réduire de 2 le seuil des tests de Perception contre les embuscades. Préparée avant le combat, la formation donne +2 initiative aux participants.',kind='action')
R('feu',85,'Tactique : Ouverture d’angle','Un seul opérateur utilise le bord d’un couvert pour ne dévoiler qu’une partie de son profil. Chaque tranche de deux succès au test de Tactiques d’escouade lui donne +1 SD.',kind='action')
R('feu',85,'Tactique : Progression en perroquet','Seuil 2 à couvert, 3 à découvert. Les participants se couvrent à tour de rôle pour avancer ; appliquer −3 au SO de l’ennemi.',kind='action')
R('feu',86,'Tactique : Repli stratégique','Seuil 3. Tous les participants doivent disposer d’une arme à distance. Ils reculent successivement pendant que les autres couvrent ; la manœuvre donne +3 SD.',kind='action')
R('feu',86,'Tactique : Sous le bouclier','Seuil 3. Un bouclier balistique protège un allié supplémentaire ; un petit véhicule ou grand drone deux à trois, un grand blindé trois à quatre, selon le MJ. Les protégés gagnent le bonus de SD du bouclier, ou la moitié de la Résistance du véhicule/drone arrondie au supérieur.',kind='action')
R('feu',86,'Tactique : Tir de suppression','Seuil 2, arme automatique et munitions suffisantes. Les succès du test de tactique déterminent le nombre de cibles possibles avec un jet d’attaque. Chaque cible réduit son SD de la VD de base de l’arme et son SO de la moitié de cette VD, arrondie au supérieur.',kind='action',tags=('rafale','suppression','automatique'))
R('feu',95,'Apprendre un art martial','Nouveau style : un mois, 7 Karma, 2 500 ¥ ; sa technique spéciale est incluse. Nouvelle technique : deux semaines, 5 Karma, 1 500 ¥. Respecter les catégories du style et les prérequis. Une technique ne s’apprend qu’une fois sauf exception explicite ; les styles n’ont pas de plafond en nombre.',topic='personnage')
R('feu',101,'Art martial : Combat à deux armes','Lors d’Attaques multiples avec plusieurs armes, gagner deux dés à répartir entre les attaques. Catégorie Armes. Cette technique de Feu nourri est distincte de la variante du même nom du Companion.',topic='combat')
R('feu',101,'Art martial : Combat au sol','Aucun malus d’attaque ou de défense pour À terre. Diviser par deux, arrondi au supérieur, le malus de défense lorsque le personnage est immobilisé. Catégorie Lutte.')
R('feu',101,'Art martial : Clé articulaire','Lors d’une immobilisation, l’option Infliger des dommages peut donner Estropié au membre saisi. Le niveau augmente de 1 par tranche de deux succès nets. Catégorie Lutte.')
R('feu',104,'État : Déséquilibré','Aucune dépense d’Atout pour une action liée à un attribut physique ou pour un test de défense. Une mineure pour retrouver son équilibre ou tomber au sol met fin à l’état. Une complication peut provoquer une chute.',tags=('état','statut'))
R('feu',104,'État : Estropié','Niveau I : les mineures impliquant le membre coûtent deux mineures. Niveau II : les majeures qui l’utilisent coûtent aussi une mineure. Niveau III : une jambe impose Entravé ; un bras donne −4 aux compétences utilisant ce bras. Les effets des niveaux se cumulent.',tags=('bras','jambe','blessure','état'))
R('feu',104,'État : Muet','Empêche de parler, sans supprimer les autres facultés. Langue des signes, messages et signaux restent possibles ; le MJ tranche les compétences affectées.',tags=('silence','état'))
R('feu',125,'Résilience après un traumatisme','Lancer 2D6, appliquer les modificateurs de circonstance et comparer à 8 − VOL. Un résultat supérieur ne provoque pas d’effet négatif ; inférieur, il peut engager une voie de traits. Le texte fourni ne tranche pas explicitement l’égalité. L’attribution ou l’aggravation d’un trait se décide avec le MJ ; le premier échec lié à un type d’événement donne aussi Mauvais souvenirs.',topic='personnage',tags=('traumatisme','voie de traits'))

R('rigger',156,'Conception : calculs finaux d’un véhicule','Après choix du châssis, de la motorisation, de la console et des options, calculer le modificateur de vitesse : Résistance finale/2 + Blindage final. Le retrancher pour moitié à l’Accélération de base ; retrancher dix fois ce modificateur à la Vitesse Max de base. La source précise les arrondis à ces étapes et des exceptions de locomotion.',topic='rigging')
R('rigger',156,'Conception : vitesse des petits drones','Après le calcul de vitesse modifiée, multiplier la Vitesse Max des petits drones par 0,75, des minidrones par 0,5 et des microdrones par 0,25. Les drones moyens ou plus grands ne subissent pas cette réduction.',topic='rigging')
R('rigger',156,'Conception : prix et disponibilité','Prix final : Points de Création × 1 000 ¥ ; fabrication personnelle possible à 50 % avec les moyens requis. Disponibilité de base 2, puis +1 De luxe, +1 Aérien, +1(L) De sécurité ou +2(I) Militaire. Retenir le plus haut de cette Disponibilité et de celle des modifications installées.',topic='rigging')
R('rigger',162,'Faire réparer un véhicule','Tarif de base d’un professionnel : 10 % de la valeur totale du véhicule par case réparée, avant négociation ou supplément. Un moniteur plein rend le véhicule détruit, mais récupération et travail en atelier peuvent encore permettre sa remise en état selon la procédure détaillée.',topic='rigging',tags=('réparation','drone','mécanicien'))
R('rigger',174,'Course-poursuite : procédure','Définir l’environnement et choisir une cible de référence pour les positions. Chaque round demande une majeure Pilotage en véhicule, ou une majeure Sprinter avec Athlétisme + AGI à pied. Résoudre le test adapté au terrain, l’Atout, l’avantage positionnel puis les changements de distance. Les règles couvrent aussi les courses à pied, aériennes et aquatiques.',topic='rigging',tags=('poursuite','chase'))
R('rigger',176,'Distances d’une course-poursuite','En véhicule : proche jusqu’à 10 m, courte 11–50 m, moyenne 51–250 m, longue 251–500 m, extrême au-delà. À pied : proche jusqu’à 3 m, courte 4–50 m. Utiliser ces catégories plutôt qu’une mesure permanente au mètre près.',topic='rigging')
R('rigger',177,'Avantage positionnel','Donne une remise d’Atout de 1 aux tests contre l’adversaire concerné, y compris aux passagers. S’il vaut contre tous les adversaires, il s’applique aussi au test obligatoire de déplacement. En terrain dégagé ou étroit, un Intervalle de vitesse au moins triple permet de choisir sa position en fin de round.',topic='rigging')
R('rigger',177,'Atout et réserve de course-poursuite','Comparer l’indice adapté à l’environnement au meilleur indice adverse, au lieu du SO/SD : le camp supérieur gagne 1 Atout. Un rigger plongé gagne aussi 1 Atout à chaque test de Pilotage. La réserve spéciale peut stocker des points réservés au Pilotage ou à la Course ; elle commence à zéro et se vide après la poursuite. Son indice dépend du câblage de contrôle ou de l’amélioration de Réaction applicable.',topic='rigging')
R('rigger',177,'Co-pilote','Action majeure libre. Décrire une aide non combattante avec Plein air, Perception, Influence ou Ingénierie. Seuil : 2 + Atout déjà stocké dans la réserve de poursuite ; réussite, +1 point à cette réserve puis davantage selon les succès, sans dépasser son maximum. Sans réserve de poursuite, le seuil est 5 et une réussite donne 1 Atout au pilote.',topic='rigging',kind='action')

R('hacker',29,'Recherche matricielle et informations privées','Une recherche ordinaire donne des informations publiques : réseaux sociaux, archives et presse. Les secrets demandent plutôt des contacts, un paradis de données ou l’accès au réseau qui les conserve.',topic='matrice',tags=('investigation','enquête','recherche'))
R('hacker',29,'Observer un serveur depuis l’extérieur','L’intérieur et l’extérieur d’un serveur ne sont pas librement visibles l’un depuis l’autre. Les appareils distants doivent être repérés ; hors serveur, Percevoir la Matrice (2), ou opposition Indice du serveur + Corruption si l’appareil lui est asservi.',topic='matrice')
R('hacker',30,'Créer ou modifier un objet de réalité augmentée','Associer l’ORA à un appareil. Créer un objet statique : Électronique (Logiciels) + LOG (4, 1 heure), étendu ; animation ou graffiti : seuil +4 ; fonctions complexes : au moins 12. Le dégrader exige un accès Utilisateur, un seuil double et un intervalle de quinze minutes. L’effacer passe par Éditer un fichier ou la destruction du support.',topic='matrice')
R('hacker',30,'Vitesse d’interface et remise d’Atout','Un utilisateur ayant une interface plus rapide que sa cible reçoit une remise d’Atout sur l’action matricielle. Hot-sim contre RA : remise de 2 ; cold-sim contre RA : remise de 1. Ce sont des remises, pas des points gagnés.',topic='matrice',tags=('hot sim','cold sim','RA','RV'))
R('hacker',30,'Analyse des menaces','Majeure légale, accès Invité. Électronique + LOG sans défense. Les succès deviennent des dés bonus de défense physique et matricielle jusqu’au début du prochain tour du hacker. Réservé aux alliés avec affichage RA relié à son PAN ; maximum de bénéficiaires égal à son Traitement de données.',topic='matrice',kind='action')
R('hacker',30,'Attaque par interception','Majeure illégale, accès Invité. Piratage (Guerre électronique) + LOG contre INT + Traitement de données, ou Corruption + Traitement de données. En cas de réussite, les communications entrantes et sortantes de l’appareil transitent par le vôtre pendant autant de minutes que les succès nets.',topic='matrice',kind='action')
R('hacker',30,'Calibrage','Majeure légale, accès Utilisateur. Électronique + LOG sans défense : +1 initiative physique par tranche de deux succès, maximum Traitement de données. Un seul Calibrage à la fois ; bonus diminuant de 1 à chaque tour. Les participants doivent avoir un affichage RA relié au PAN ; leur nombre ne dépasse pas l’indice d’appareil du hacker.',topic='matrice',kind='action')
R('hacker',30,'Commande retardée','Majeure illégale, accès Invité. Piratage (Guerre électronique) + LOG contre Traitement de données + Firewall ou Autopilote + Firewall. Envoyer une instruction qui sera exécutée plus tard comme si elle venait du propriétaire. Couper le sans-fil ne l’annule pas ; rebooter l’appareil avant son déclenchement la supprime.',topic='matrice',kind='action')
R('hacker',32,'Déni de service','Majeure illégale, accès Invité. Piratage (Hacking) + LOG contre VOL + Firewall ou Firewall ×2. Les succès nets ×2 deviennent un malus de dés aux tests utilisant l’appareil, jusqu’à la fin du prochain round.',topic='matrice',kind='action')
R('hacker',32,'Détournement d’infrastructure','Majeure illégale, accès Administrateur. Piratage (Hacking) + LOG contre INT + Firewall ou Corruption + Firewall. Contrôler un appareil simple similaire par succès net, sans réaliser d’attaque. Dépenser une majeure à chaque round pour conserver ce contrôle.',topic='matrice',kind='action')
R('hacker',32,'En dérangement','Mineure illégale, accès Invité. Piratage (Guerre électronique) + LOG contre INT + Corruption ou Corruption ×2. L’appareil ne peut envoyer ni recevoir de messages pendant un nombre de minutes égal aux succès nets.',topic='matrice',kind='action')
R('hacker',32,'Exploiter une backdoor connue','Majeure illégale liée à Corruption, accès Invité. Piratage (Hacking) + LOG contre VOL + Firewall ou Firewall ×2. Ne demande pas de sondage préalable. Le hacker ne gagne ni ne dépense d’Atout ; la cible reçoit une remise de 1. Une réussite donne un accès Administrateur qui ne compte pas comme illégal pour ce seul accès ; les actions ultérieures illégales augmentent toujours le SS. Un échec ne déclenche pas automatiquement l’alerte.',topic='matrice',kind='action')
R('hacker',32,'Mascarade','Majeure illégale, accès Invité. Piratage (Guerre électronique) + LOG contre INT + Traitement de données ou Corruption + Traitement de données. Imiter un persona une minute par succès net ; l’effet cesse quand l’original se déconnecte. Ne change pas la propriété et ne trompe pas les contrôles renforcés des virements majeurs ou transferts de propriétaire.',topic='matrice',kind='action')
